TGLV350.Regular.scalarTomitaResolvent_double_cut_balance (P : TGLExt.SiteProfile) (ε η : ℝ) (hε : 0 < ε) (hη : 0 < η) :
  have π := TGLV350.Regular.scalarGNSRepresentation P;
  have J := TGLV350.Regular.scalarTomitaPolarFactor P;
  have C := π ⟨TGLV350.Regular.regularInverseGeneratorCutoff P ε, ⋯⟩;
  have D := TGLV350.Regular.antiunitaryConjugate J (π ⟨TGLV350.Regular.regularInverseGeneratorCutoff P η, ⋯⟩);
  Commute (TGLV350.Regular.scalarTomitaResolvent P) C ∧
    Commute (TGLV350.Regular.scalarTomitaResolvent P) D ∧
      (1 - TGLV350.Regular.scalarTomitaResolvent P) * C *
          TGLV350.Regular.antiunitaryConjugate J (π (TGLV350.Regular.regularDomainCut P η)) =
        TGLV350.Regular.scalarTomitaResolvent P * π (TGLV350.Regular.regularDomainCut P ε) * D
'TGLV350.Regular.scalarTomitaResolvent_double_cut_balance' depends on axioms: [propext, Classical.choice, Quot.sound]
